    {
      "rank": 1,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Two-dimensional conformal field theory supplied a remarkably universal and exact framework for critical phenomena, with enduring influence across statistical and quantum physics.",
        "attribution": "Polyakov was a foundational architect; the named framework also centrally depends on Belavin and Zamolodchikov, whose posthumous ineligibility constrains an award.",
        "maturity": "The theory has been tested and used for decades, and its conceptual mechanism is exceptionally well understood.",
        "uncertainties": [
          "Whether the indivisible historical contribution can be recognized fairly when key co-creators are ineligible."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Bertrand I. Halperin",
        "A. Peter Young"
      ],
      "assessment": {
        "nobel_worthiness": "The defect-based account of two-dimensional melting is a clean, powerful example of statistical physics revealing universal collective behavior.",
        "attribution": "Halperin, Nelson, and Young made complementary essential theoretical contributions; Nelson's posthumous ineligibility limits complete recognition.",
        "maturity": "The hexatic phase and the central predictions have received extensive theoretical, numerical, and experimental support over many decades.",
        "uncertainties": [
          "The breadth and sharpness of experimental realization vary substantially among two-dimensional materials and soft-matter systems."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Gavin E. Crooks",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "Fluctuation relations transformed nonequilibrium statistical mechanics by yielding exact statements far from equilibrium and a coherent stochastic-thermodynamic framework.",
        "attribution": "Jarzynski, Crooks, Evans, and Seifert have distinct but tightly linked claims; the three proposed laureates capture the principal modern theoretical formulation.",
        "maturity": "The relations are rigorously established, widely applied, and experimentally investigated from single molecules to mesoscopic systems.",
        "uncertainties": [
          "Credit allocation between the original fluctuation theorem and later unifying formulations is intrinsically difficult."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Antoine Georges",
        "Gabriel Kotliar",
        "Dieter Vollhardt"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strong electronic correlations quantitatively tractable and changed the working language of correlated-electron physics.",
        "attribution": "Georges, Kotliar, and Vollhardt are appropriate core figures in developing and establishing the method.",
        "maturity": "Its successes for correlation-driven phenomena and its broad methodological uptake are long established.",
        "uncertainties": [
          "The prize case is for a highly influential theoretical method rather than one discrete experimental discovery."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Peter W. Shor",
        "Alexei Kitaev",
        "Andrew M. Steane"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction identified the essential mechanism by which fragile quantum information can be protected, enabling fault-tolerant computation in principle.",
        "attribution": "Shor, Kitaev, and Steane made foundational and complementary contributions to codes and fault-tolerance.",
        "maturity": "The principles are understood and increasingly demonstrated, though fully fault-tolerant large-scale machines remain unrealized.",
        "uncertainties": [
          "The ultimate practical scale and resource overhead of fault-tolerant quantum computation remain uncertain."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Yakir Aharonov",
        "Michael Berry"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and geometric phase exposed the physical significance of phase, gauge potentials, and quantum geometry across many domains.",
        "attribution": "Aharonov and Berry anchor two distinct but related foundational contributions; each discovery also has important collaborators not represented here.",
        "maturity": "Both effects are thoroughly established experimentally and have become standard conceptual tools in modern physics.",
        "uncertainties": [
          "Combining two historically distinct effects into a single award risks blurring their separate attributions."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Mark A. Kasevich",
        "Christian J. Bordé",
        "David E. Pritchard"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry converted coherent matter waves into a uniquely precise platform for gravity measurements, inertial sensing, and tests of fundamental physics.",
        "attribution": "Bordé, Pritchard, and Kasevich represent major theoretical and experimental strands in the field's development.",
        "maturity": "The techniques are mature and repeatedly validated, with broad scientific and technological consequences.",
        "uncertainties": [
          "The field has many pivotal contributors, making a three-person attribution unusually selective."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the quantum account of primordial structure offer a profound explanatory framework connecting fundamental physics to observed cosmological structure.",
        "attribution": "Guth, Linde, and Mukhanov made central, identifiable contributions to inflationary dynamics and primordial fluctuations.",
        "maturity": "Its predictions have influential observational support, especially in cosmic microwave background structure.",
        "uncertainties": [
          "Inflation's underlying physical realization and the uniqueness of its observational interpretation remain unresolved."
        ]
      }
    }
  ]
